{
  "action": "applyTeacher",
  "data": {
    "bio": "I have taught bookkeeping to traders for ten years.",
    "expertise": "Bookkeeping"
  }
}

{
  "action": "updateMeta",
  "data": {
    "id": "{{courseId}}",
    "title": "Postman Course {{$timestamp}}",
    "summary": "Created from the Postman collection",
    "category": "Testing",
    "outline": "Variables\nEquations\nWord problems",
    "level": "beginner",
    "language": "English",
    "description": "A course created to demonstrate the approval workflow."
  }
}

{
  "action": "saveContent",
  "data": {
    "id": "{{courseId}}",
    "content": {
      "sections": [
        {
          "id": "s1",
          "title": "Getting started",
          "items": [
            {
              "id": "l1",
              "kind": "lesson",
              "title": "Welcome",
              "type": "text",
              "body": "Hello and welcome to the course.",
              "preview": true
            },
            {
              "id": "l2",
              "kind": "lesson",
              "title": "Watch this",
              "type": "video",
              "videoUrl": "https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4"
            },
            {
              "id": "q1",
              "kind": "quiz",
              "title": "Check-in",
              "questions": [
                {
                  "id": "a",
                  "type": "single",
                  "prompt": "2 + 2 = ?",
                  "options": [
                    {
                      "id": "x",
                      "text": "4"
                    },
                    {
                      "id": "y",
                      "text": "5"
                    }
                  ],
                  "correct": [
                    "x"
                  ]
                },
                {
                  "id": "b",
                  "type": "truefalse",
                  "prompt": "The sky is blue",
                  "correct": [
                    "true"
                  ]
                },
                {
                  "id": "c",
                  "type": "multi",
                  "prompt": "Pick the even numbers",
                  "options": [
                    {
                      "id": "m",
                      "text": "2"
                    },
                    {
                      "id": "n",
                      "text": "3"
                    },
                    {
                      "id": "o",
                      "text": "4"
                    }
                  ],
                  "correct": [
                    "m",
                    "o"
                  ]
                }
              ]
            }
          ]
        }
      ],
      "completion": {
        "lessons": [
          "l1",
          "l2"
        ],
        "quizzes": [
          "q1"
        ]
      }
    }
  }
}

